  "billing.cancel.doneWithEnd": "तुम्हाला {endDate} पर्यंत पूर्ण प्रवेश मिळतो. त्या तारखेनंतर तुम्हाला {graceDays} दिवसांचा फक्त-वाचन सवलत कालावधी मिळतो — तुम्ही अजूनही लॉग इन करून तुमची उत्पादने पाहू शकता, पण तुम्ही काहीही जोडू, संपादित करू, हटवू, स्कॅन करू, आयात करू, निर्यात करू किंवा बदलू शकत नाही. {gracePart}",
  "billing.cancel.graceEndsOn": "15 दिवसांचा सवलत कालावधी {date} रोजी संपल्यानंतर, तुमचे खाते आणि त्यातील सर्व माहिती कायमची हटवली जाईल आणि ती परत मिळवता येणार नाही.",
