  "billing.cancel.alreadyCanceledNoEnd": "ती सध्याच्या सशुल्क कालावधीच्या शेवटी संपते. तोपर्यंत तुम्हाला पूर्ण प्रवेश मिळतो.",
  "billing.cancel.appStoreNote": "तुम्ही कधी Google Play किंवा Apple App Store मार्फत सदस्यता घेतल्यास, तुम्हाला त्या दुकानाच्या सदस्यता सेटिंग्जमधून ती रद्द करावी लागू शकते. हा संवाद अॅप-दुकान बिलिंग थांबवू शकत नाही. अॅप अनइंस्टॉल केल्याने किंवा तुमचे StockHaven खाते हटवल्याने दुकान सदस्यता रद्द होत नाही.",
