  "exports.eyebrow": "डेटा",
  "exports.title": "निर्यात आणि बॅकअप",
  "exports.subtitleStart": "डाउनलोड नेहमी मर्यादित असतात",
  "exports.subtitleRest": ". प्रत्येक फाइल व्यवसायाचे नाव आणि ती बनवलेल्या तारखेसह लेबल केलेली असते.",
  "exports.createBusinessFirst": "आधी व्यवसाय तयार करा — निर्यात व्यवसायाची असते, अॅपची नाही.",
  "exports.lockedTitle": "CSV आणि Excel निर्यात हे Business वैशिष्ट्य आहे",
  "exports.lockedDesc": "तुमचे कार्यक्षेत्र Essentials योजनेवर आहे. Business CSV आणि Excel निर्यात, साठा मूल्यांकन, अमर्यादित उत्पादने आणि कर्मचारी, पुरवठादार, खरेदी आणि बंडल जोडते.",
  "exports.seeBusiness": "Business मध्ये काय समाविष्ट आहे ते पहा",
  "exports.whatTheseAre": "या फाइल काय आहेत",
  "exports.about1": "प्रत्येक डेटासंच CSV किंवा खरी Excel कार्यपुस्तिका (.xlsx) म्हणून येतो — संपूर्ण इन्व्हेंटरी कार्यपुस्तिका फक्त Excel आहे, प्रति डेटासंच एक पत्रक. CSV फाइल Excel, Numbers, Google Sheets आणि बहुतेक साठा अॅपमध्ये उघडतात. UTF-8 मजकूर, अवतरण केलेले स्वल्पविराम, नोंदींमधील ओळ खंड आणि कोडमधील आघाडीचे शून्य सर्व जतन केले जातात आणि सूत्रासारखे सुरू होणारे सेल निष्प्रभ केले जातात म्हणजे स्प्रेडशीट त्यांना मजकूर म्हणून उघडते.",
  "exports.about2": "Excel फाइलमध्ये, SKU, UPC, ISBN आणि बारकोड मजकूर सेल असतात — कधीही वैज्ञानिक संकेतन नाही आणि कधीही छाटलेले शून्य नाही — स्तंभ रुंदी, शीर्षक गाळण्या आणि चलन किंवा प्रमाण स्वरूप लागू केलेले. संपूर्ण इन्व्हेंटरी कार्यपुस्तिका उत्पादने, साठा पातळी, ठिकाणे आणि हालचाली वेगळ्या पत्रकांवर ठेवते.",
  "exports.about3": "खूप मोठ्या निर्यात प्रति डेटासंच 20,000 पंक्तींवर थांबतात — तसे झाल्यावर फाइलचे नाव तसे सांगते (truncated-20000), त्यामुळे अंशिक फाइल कधीही संपूर्ण म्हणून जात नाही.",
  "exports.about4": "बॅकअप म्हणजे तुमच्या डेटाचा स्नॅपशॉट आहे, एक-क्लिक पुनर्स्थापना नाही. ते पुनर्स्थापित करणे हाताने, आधी-पहा काम आहे, त्यामुळे फाइल सुरक्षित ठेवा — अॅपमधील काहीही हटवलेला व्यवसाय त्यातून अजून पुन्हा तयार करू शकत नाही. अॅप कोड आणि Base44 प्लॅटफॉर्म बॅकअप या फाइलपासून वेगळे हाताळले जातात.",
  "exports.about5": "फोटो आणि जोडण्या त्यांच्या साठवलेल्या लिंक म्हणून सूचीबद्ध केल्या जातात — प्रतिमा फाइल स्वतः डाउनलोडमध्ये पॅक केल्या जात नाहीत.",
  "exports.backupTitle": "संपूर्ण बॅकअप",
  "exports.backupDesc": "या व्यवसायाची उत्पादने, ठिकाणे, साठा पातळी, संपूर्ण हालचाल खातेवही, पुरवठादार, खरेदी, ऑर्डर, परतावे, मोजणी आणि सूची असलेली एक फाइल — अधिक त्याच्या प्रोफाइल सेटिंग्ज. ती तुमच्या नियंत्रणात कुठेतरी ठेवा.",
  "exports.backupIncludes1": "उत्पादने, कोड, खर्च आणि नोंदी",
  "exports.backupIncludes2": "ठिकाणे आणि प्रति-ठिकाण प्रमाण",
