  "reports.missingMoney": "या दृश्यातील {units} एककांची कोणतीही {label} नोंद नाही. गहाळ पैसे कधीही शून्य मानले जात नाहीत — ती मोकळी म्हणून मोजण्याऐवजी आकड्यांमधून वगळली जातात. त्या उत्पादनांवर आकडा जोडा आणि एकूण भरतील.",
  "reports.movementsCapped": "फक्त सर्वात नवीन {cap} खातेवही नोंदी वाचल्या, त्यामुळे यापेक्षा जुन्या हालचाली एकूणमध्ये नाहीत. कालावधी अरुंद करा म्हणजे विशिष्ट कालखंडासाठी अचूक आकडे दिसतील.",
  "reports.footnote": "विक्री प्रत्येक उत्पादनाची सध्याची किरकोळ किंमत वापरते, प्राप्ती साठा आल्यावर नोंदवलेला खर्च वापरते आणि तोटा सध्याचा एकक खर्च वापरतो. गहाळ पैसे कधीही शून्य मानले जात नाहीत — आकडा कळेपर्यंत क्षेत्र रिकामे ठेवा. अहवाल म्हणजे दृश्य आहे, दस्तऐवज नाही: तुम्ही चालवाल तेव्हा तुमच्या नोंदींमध्ये काहीही लिहिले जात नाही.",
