  "print.supplierBlockedDesc": "पुरवठादार दस्तऐवज Business योजनेसोबत जातात — पुरवठादार, खरेदी आणि खरेदी ऑर्डर. तुमच्याकडे आता जे आहे ते सर्व चालत राहते.",
