  "settings.cancelTerms.appleLink": "Apple रद्दीकरण सूचना",
  "settings.cancelTerms.googlePlayLink": "Google Play रद्दीकरण सूचना",
  "settings.cancelTerms.graceTitle": "तुमचा सशुल्क कालावधी संपल्यानंतर — 15 दिवसांची सवलत, मग हटवणे:",
  "settings.cancelTerms.intro": "या सशुल्क Luminous StockHaven सदस्यतांसाठी अटी आहेत. वेबसाइट सदस्यता बिलिंग Stripe मार्फत आहे. तुम्ही खालील सदस्यता रद्द करा बटण वापरून तुमची सदस्यता स्वतः कधीही रद्द करू शकता — कर्मचारी मंजुरीची गरज नाही. रद्दीकरण आणि परतावा विनंत्या अधिकृत ग्राहक समर्थन संपर्क, theluminousbookshop@outlook.com मार्फतही हाताळल्या जाऊ शकतात.",
  "settings.cancelTerms.noApprovalBody": "तुम्ही तुमची सदस्यता स्वतः कधीही रद्द करू शकता. कर्मचारी मंजुरीची गरज नाही. बिलिंग प्रदाता रद्दीकरणाची पुष्टी केल्यानंतरच भविष्यातील नूतनीकरण थांबते.",
  "settings.cancelTerms.noApprovalTitle": "मंजुरीशिवाय रद्द करा:",
  "settings.cancelTerms.paymentBody": "सशुल्क चाचण्यांसाठी, सात दिवसांच्या चाचणीसाठी साइनअपच्या वेळी पेमेंट पद्धत आवश्यक आहे. लागू चाचणी रद्दीकरण मुदतीत रद्द केले नाही तर, निवडलेल्या मासिक योजनेवर चाचणीनंतर आपोआप शुल्क आकारले जाईल. किंमत, पहिली बिलिंग तारीख आणि प्रदाता-विशिष्ट रद्दीकरण मुदत साइनअपदरम्यान दाखवलीच पाहिजे. चाचणी बिलिंग Stripe मार्फत आहे.",
  "settings.cancelTerms.paymentTitle": "पेमेंट पद्धत आणि आपोआप नूतनीकरण:",
  "settings.cancelTerms.remainingBody": "तुम्ही आधीच बिलिंग कालावधीसाठी पैसे भरले असल्यास, तुम्ही त्या पडताळलेल्या सशुल्क-अंतिम तारखेपर्यंत प्रवेश ठेवू शकता. लवकर समाप्तीसाठी योग्य प्रदाता पुष्टी आणि लागू परतावा हाताळणी आवश्यक आहे. मोफत-चाचणी प्रवेश प्रदाता-पुष्टी केलेल्या चाचणी समाप्ती तारखेनुसार संपतो.",
  "settings.cancelTerms.remainingTitle": "शिल्लक प्रवेश:",
  "settings.cancelTerms.storesBody": "तुम्ही कधी Google Play किंवा Apple App Store मार्फत सदस्यता घेतल्यास, तुमची सदस्यता त्या दुकानाद्वारे आकारली आणि व्यवस्थापित केली जाते. तुम्हाला ती सदस्यता घेण्यासाठी वापरलेल्या त्याच Google किंवा Apple खात्याच्या सदस्यता विभागात थेट रद्द करावी लागू शकते. वेगळी वेबसाइट सदस्यता रद्द केल्याने, हे अॅप अनइंस्टॉल केल्याने किंवा Luminous StockHaven खाते हटवण्याची विनंती केल्याने दुकान-आकारलेली सदस्यता आपोआप रद्द होत नाही. तुम्हाला कोण आकारतो याची पुष्टी करण्यासाठी तुमची खरेदी पावती तपासा.",
  "settings.cancelTerms.storesTitle": "Google Play आणि Apple App Store सदस्यता (तुम्ही कधी दुकानामार्फत सदस्यता घेतल्यास):",
  "settings.cancelTerms.title": "रद्दीकरण अटी आणि शर्ती",
  "settings.cancelTerms.trialBody": "सात दिवसांची चाचणी प्रति पात्र ग्राहक फक्त एकदाच वापरता येते. चाचणी किंवा सदस्यता रद्द केल्याने दुसरी चाचणी मिळत नाही; परत येणाऱ्या ग्राहकांनी सशुल्क सदस्यता निवडलीच पाहिजे.",
  "settings.cancelTerms.trialTitle": "एक मोफत चाचणी:",
  "settings.canceled.endsOn": "ही सदस्यता रद्द केली आहे आणि {date} रोजी संपते. तोपर्यंत तुम्हाला पूर्ण प्रवेश मिळतो.",
  "settings.delete.checking": "विद्यमान हटवण विनंती तपासत आहे…",
  "settings.delete.description": "तुमचे Luminous StockHaven साइन-इन खाते काढण्याची विनंती करा.",
  "settings.delete.dialogDescription": "हे खाते हटवण्याच्या पुनरावलोकनाची विनंती करते. ते तुमचे लॉगिन किंवा इन्व्हेंटरी ताबडतोब काढत नाही आणि कोणतीही Stripe सदस्यता रद्द करत नाही. तुम्हाला विनंती सादर करायची आहे याची पुष्टी करण्यासाठी {word} टाइप करा.",
