  "payroll.dd.steps.body": "1. ACH देयके पाठवू शकेल असे व्यावसायिक बँक खाते तुम्हाला हवे. 2. प्रत्येक संघ सदस्याकडून स्वाक्षरी केलेला प्राधिकरण फॉर्म गोळा करा — रद्द केलेला चेक आकडे पडताळायला मदत करतो. 3. पैसे वेळेवर पोहोचावेत म्हणून पगाराच्या दिवसाच्या 2-3 कामकाजाचे दिवस आधी वेतनपट पाठवा. 4. बहुतेक राज्यांत संघ सदस्याची लेखी संमती आवश्यक असते. हे अॅप फॉर्म गोळा करते आणि पायऱ्या समजावते — पैसे प्रत्यक्ष पाठवणे तुमच्या स्वतःच्या बँकेतून होते.",
