  "workforce.messages.emptyThread": "अद्याप संदेश नाहीत. सुरुवात करण्यासाठी नमस्कार म्हणा.",
  "workforce.messages.help": "तुमच्या संघाशी खासगी एकास-एक संदेश — दुसऱ्या अॅपची गरज नाही. संभाषणातील फक्त दोनच लोक ते वाचू शकतात, आणि व्यवसाय मालक, जे त्यांच्या दुकानावर देखरेख करतात.",
