  "pos.events.heldPlanNote": "खालील काही विक्री हे दुकान Business योजनेवर नसताना आली. त्या सुरक्षित ठेवल्या गेल्या आणि काहीही मोजले गेले नाही. आता दुकान Business वर असल्याने तुम्ही त्या मोजू शकता.",
